const randomInt=max=>{if(globalThis.crypto?.getRandomValues){const v=new Uint32Array(1);const limit=Math.floor(4294967296/max)*max;do{crypto.getRandomValues(v);}while(v[0]>=limit);return v[0]%max;}return Math.floor(Math.random()*max);};
const shuffle=items=>{const a=items.slice();for(let i=a.length-1;i>0;i--){const j=randomInt(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;};
const startTopic=key=>{topic=key;index=0;score=0;completedRecorded=false;sessionQuestions=shuffle(BANK[key]).slice(0,30).map(q=>{const choices=shuffle(q[1].map((value,i)=>({value,correct:i===q[2]})));return [q[0],choices.map(c=>c.value),choices.findIndex(c=>c.correct),q[3]];});render();playCue('question');};
